  KEY `forhandler_id_idx` (`forhandler_id`),
  CONSTRAINT `forhandler_id` FOREIGN KEY (`forhandler_id`) REFERENCES `forhandler` (`forhandler_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
